import React from "react";
import { FaCheckCircle } from "react-icons/fa";

const Features = () => {
    return (
        <section className="px-8 py-24 bg-white">
            <div className="max-w-6xl mx-auto text-center">

                <h2 className="text-3xl font-bold text-gray-900">
                    Designed for Modern Infrastructure
                </h2>

                <p className="mt-3 text-gray-500">
                    Built for efficiency, scalability, and automation
                </p>

                <div className="mt-16 grid md:grid-cols-3 gap-10">

                    {["Usage Tracking", "Billing System", "Community Management"].map((title, i) => (
                        <div key={i} className="p-8 rounded-2xl bg-gray-50 hover:shadow-2xl transition text-left">

                            <h3 className="font-semibold text-lg mb-3">{title}</h3>

                            <p className="text-gray-500 text-sm mb-4">
                                Powerful tools to manage and monitor efficiently.
                            </p>

                            <div className="space-y-2 text-sm text-gray-600">
                                <p className="flex items-center gap-2">
                                    <FaCheckCircle className="text-blue-600" /> Real-time insights
                                </p>
                                <p className="flex items-center gap-2">
                                    <FaCheckCircle className="text-blue-600" /> Automated processes
                                </p>
                            </div>

                        </div>
                    ))}

                </div>
            </div>
        </section>
    );
};

export default Features;
